// 只消费 NgDetectedEvent / WorkOrderCompletedEvent，兼容 node-red-contrib-opcua
// 的 eventFields 数组、Variant({value})，以及自定义字段的 "2:Field" 键名。
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
}
const fromFieldArray = arr => {
    const o = {};
    for (let i = 0; i < arr.length; i++) {
        const f = arr[i];
        if (!f || typeof f !== 'object') continue;
        let k = f.name || f.browseName || f.displayName || f.key;
        if (k && typeof k === 'object') k = k.text || k.Text || k.value || JSON.stringify(k);
        if (k) o[String(k)] = f.value !== undefined ? f.value : f.Value;
    }
    return o;
};
if (Array.isArray(p)) p = fromFieldArray(p);
if (!p || typeof p !== 'object') p = {};
if (Array.isArray(p.eventFields)) {
    p = Object.assign({}, p, fromFieldArray(p.eventFields));
} else if (p.eventFields && typeof p.eventFields === 'object') {
    p = Object.assign({}, p, p.eventFields);
}

// 事件过滤字段写成 "2:WorkOrderId" 时，contrib 会原样作为 payload key 输出。
// 保留原 key，同时补一份去命名空间前缀的别名，供后续统一读取。
Object.keys(p).forEach(k => {
    const nk = String(k).replace(/^ns=\d+;/i, '').replace(/^\d+:/, '');
    if (nk !== k && p[nk] === undefined) p[nk] = p[k];
});

const unwrap = v => (v && typeof v === 'object' && !Array.isArray(v) && v.value !== undefined) ? v.value : v;
const asText = v => {
    v = unwrap(v);
    if (v === undefined || v === null) return '';
    if (typeof v === 'object') return String(v.text || v.Text || v.value || JSON.stringify(v));
    return String(v);
};
const pickRaw = (obj, names, dflt) => {
    for (let i = 0; i < names.length; i++) {
        const v = obj[names[i]];
        if (v !== undefined && v !== null) return v;
    }
    return dflt;
};
const toMs = v => {
    v = unwrap(v);
    if (v === undefined || v === null) return NaN;
    if (typeof v === 'number') return v;
    if (typeof v === 'string') return Date.parse(v);
    if (typeof v.getTime === 'function') return v.getTime();
    if (typeof v.valueOf === 'function') {
        const n = v.valueOf();
        if (typeof n === 'number' && isFinite(n)) return n;
    }
    if (v.date && typeof v.date.getTime === 'function') return v.date.getTime();
    return Date.parse(String(v));
};

// contrib 遇到 EventType(NodeId) 时会用事件类型的 BrowseName 作为 key，
// 因此优先从 key 识别事件类型。
const typeKey = Object.keys(p).find(k => /(?:NgDetected|WorkOrderCompleted|InspectionFinished)EventType$/i.test(k));
const rawEt = typeKey || pickRaw(p, ['eventType', 'EventType', 'eventTypeName', 'EventTypeName'], '') || msg.eventType || '';
const et = asText(rawEt);
const now = Date.now();
const rawSrc = pickRaw(p, ['sourceTimestamp', 'SourceTimestamp', 'time', 'Time', 'receiveTime', 'ReceiveTime'], null);
const parsedTs = toMs(rawSrc);
const ts = isFinite(parsedTs) ? parsedTs : now;
const age = now - ts;
if (age > 60000) {
    node.warn('[陈旧事件丢弃] age=' + Math.round(age / 1000) + 's type=' + et);
    return null;
}
const occurredAt = new Date(ts).toISOString();
const workOrderId = asText(pickRaw(p, ['workOrderId', 'WorkOrderId'], '')).trim();
const serialNumber = asText(pickRaw(p, ['serialNumber', 'SerialNumber'], '')).trim();
const imageId = asText(pickRaw(p, ['imageId', 'ImageId'], '')).trim();
const confidenceRaw = unwrap(pickRaw(p, ['confidence', 'Confidence'], null));
let confidence = confidenceRaw === null || confidenceRaw === '' ? null : Number(confidenceRaw);
if (confidence !== null && (!isFinite(confidence) || confidence < 0 || confidence > 1)) confidence = null;
const rawResult = asText(pickRaw(p, ['result', 'Result'], ''));
const defectType = asText(pickRaw(p, ['defectType', 'DefectType'], '')).trim();
const asNumber = (v, dflt) => {
    v = unwrap(v);
    if (Array.isArray(v)) {
        if (v.length === 2) return Number(v[0]) * 4294967296 + Number(v[1]);
        if (v.length === 1) return Number(v[0]);
        return dflt;
    }
    const n = Number(v);
    return isFinite(n) ? n : dflt;
};
const hasDoneFields = p.InspectCount !== undefined || p.inspectCount !== undefined ||
                      p.NgRate !== undefined || p.ngRate !== undefined;

// 唯一发令枪：NG 只认 NgDetectedEvent，完工只认 WorkOrderCompletedEvent。
const isDone = /WorkOrderCompleted/i.test(et) || (hasDoneFields && !/InspectionFinished/i.test(et));
const isNg = /NgDetected/i.test(et) ||
             (!/InspectionFinished/i.test(et) && !isDone && !rawResult && defectType !== '');

if (isNg) {
    if (!workOrderId || !serialNumber || !defectType) {
        node.error('[契约校验失败] NgDetectedEvent 缺少 workOrderId/serialNumber/defectType，已丢弃', msg);
        return null;
    }
    return [{
        workOrderId: workOrderId,
        serialNumber: serialNumber,
        defectType: defectType,
        confidence: confidence,
        imageId: imageId,
        occurredAt: occurredAt
    }, null];
}
if (isDone) {
    if (!workOrderId) {
        node.error('[契约校验失败] WorkOrderCompletedEvent 缺少 workOrderId，已丢弃', msg);
        return null;
    }
    const inspectCount = asNumber(pickRaw(p, ['inspectCount', 'InspectCount'], 0), 0);
    const okCount = asNumber(pickRaw(p, ['okCount', 'OkCount'], 0), 0);
    const ngCount = asNumber(pickRaw(p, ['ngCount', 'NgCount'], 0), 0);
    const ngRate = asNumber(pickRaw(p, ['ngRate', 'NgRate'], -1), -1);
    return [null, {
        workOrderId: workOrderId,
        inspectCount: isFinite(inspectCount) ? inspectCount : 0,
        okCount: isFinite(okCount) ? okCount : 0,
        ngCount: isFinite(ngCount) ? ngCount : 0,
        ngRate: isFinite(ngRate) ? ngRate : -1,
        occurredAt: occurredAt
    }];
}
return null;

// 防重：同时按 serialNumber+occurredAt（M2）与 serialNumber（M1 单件唯一）兜底
const sn = String(msg.serialNumber || '').trim();
if (!sn) { node.error('[契约校验失败] NG 事件缺少 serialNumber，已丢弃'); return null; }
const occurredAt = String(msg.occurredAt || '');
const fp = sn + '|' + occurredAt;
const seen = flow.get('ngSeen') || {};
const snSeen = flow.get('ngSnSeen') || {};
if (seen[fp] || snSeen[sn]) {
    node.warn('[重复NG丢弃] serialNumber=' + sn + ' occurredAt=' + occurredAt);
    return null;
}
seen[fp] = 1;
snSeen[sn] = 1;
const keys = Object.keys(seen);
if (keys.length > 500) delete seen[keys[0]];
const snKeys = Object.keys(snSeen);
if (snKeys.length > 500) delete snSeen[snKeys[0]];
flow.set('ngSeen', seen);
flow.set('ngSnSeen', snSeen);
return msg;

// 只做告警削峰，不阻断 NG 开单：10s 窗内合并计数，超窗亮一次灯
const last = flow.get('lastAlarmAt') || 0;
const now = Date.now();
if (now - last < 10000) {
    flow.set('alarmSuppressed', (flow.get('alarmSuppressed') || 0) + 1);
    node.status({ fill: 'yellow', shape: 'ring', text: 'NG告警抑制中' });
    return null;
}
const merged = flow.get('alarmSuppressed') || 0;
flow.set('lastAlarmAt', now);
flow.set('alarmSuppressed', 0);
node.warn('[NG报警] serialNumber=' + msg.serialNumber + ' defect=' + msg.defectType +
          (merged ? '（已合并抑制 ' + merged + ' 条）' : ''));
node.status({ fill: 'red', shape: 'dot', text: 'NG' });
return null;

// NG 开单入队：报文严格按 M1 §3.1，字段名不增不减
const MAX_QUEUE = 100;
const q = flow.get('buf') || [];
const id = 'ng|' + msg.serialNumber + '|' + msg.occurredAt;
if (q.some(it => it.id === id)) {
    node.warn('[重复入队丢弃] ' + id);
    return null;
}
while (q.length >= MAX_QUEUE) {
    let dropIdx = -1;
    for (let i = 0; i < q.length; i++) {
        if (q[i].status === 'PENDING') { dropIdx = i; break; }
    }
    const dropped = q.splice(dropIdx >= 0 ? dropIdx : 0, 1)[0];
    node.warn('[缓冲溢出] 上限 ' + MAX_QUEUE + '，丢弃最旧 ' + dropped.id);
}
q.push({
    id: id,
    type: 'ng',
    url: 'http://127.0.0.1:1880/mes/ng-order',
    body: {
        workOrderId: msg.workOrderId,
        serialNumber: msg.serialNumber,
        defectType: msg.defectType,
        confidence: msg.confidence,
        imageId: msg.imageId,
        occurredAt: msg.occurredAt
    },
    attempts: 0,
    nextAt: 0,
    status: 'PENDING'
});
flow.set('buf', q);
node.status({ fill: 'yellow', shape: 'dot', text: '队列=' + q.length });
node.warn('[入队] NG ' + msg.serialNumber + ' 队列=' + q.length);
return null;

// 报工防重：workOrderId 指纹，同一工单只报工一次
const wo = String(msg.workOrderId || '').trim();
if (!wo) { node.error('[契约校验失败] 报工事件缺少 workOrderId，已丢弃'); return null; }
const seen = flow.get('doneSeen') || {};
if (seen[wo]) { node.warn('[重复报工丢弃] ' + wo); return null; }
seen[wo] = 1;
const keys = Object.keys(seen);
if (keys.length > 500) delete seen[keys[0]];
flow.set('doneSeen', seen);
return msg;

// 报工入队：字段严格按 M1 §3.1 接口 2
const MAX_QUEUE = 100;
const q = flow.get('buf') || [];
const id = 'done|' + msg.workOrderId;
if (q.some(it => it.id === id)) {
    node.warn('[重复入队丢弃] ' + id);
    return null;
}
while (q.length >= MAX_QUEUE) {
    let dropIdx = -1;
    for (let i = 0; i < q.length; i++) {
        if (q[i].status === 'PENDING') { dropIdx = i; break; }
    }
    const dropped = q.splice(dropIdx >= 0 ? dropIdx : 0, 1)[0];
    node.warn('[缓冲溢出] 上限 ' + MAX_QUEUE + '，丢弃最旧 ' + dropped.id);
}
q.push({
    id: id,
    type: 'complete',
    url: 'http://127.0.0.1:1880/mes/complete',
    body: {
        workOrderId: msg.workOrderId,
        inspectCount: msg.inspectCount,
        okCount: msg.okCount,
        ngCount: msg.ngCount,
        ngRate: msg.ngRate
    },
    createdAt: msg.occurredAt,
    attempts: 0,
    nextAt: 0,
    status: 'PENDING'
});
flow.set('buf', q);
node.status({ fill: 'yellow', shape: 'dot', text: '队列=' + q.length });
node.warn('[入队] 报工 ' + msg.workOrderId + ' 队列=' + q.length);
return null;

// 单飞行发送泵：PENDING -> SENDING -> SUCCESS 出队 / PENDING 退避 / FAILED 死信
// 同一时刻只允许一条 SENDING；1s 定时器只负责“找下一条”
const q = flow.get('buf') || [];
const now = Date.now();
const RETRY_DELAYS = [1000, 2000, 4000];

const sendDead = (item, reason) => {
    const idx = q.findIndex(it => it.id === item.id);
    if (idx >= 0) q.splice(idx, 1);
    const dead = flow.get('dead') || [];
    dead.push(Object.assign({}, item, { lastStatus: reason, failedAt: new Date().toISOString() }));
    if (dead.length > 100) dead.shift();
    flow.set('buf', q);
    flow.set('dead', dead);
    node.error('[死信FAILED] ' + item.type + ' ' + item.id + ' 重试3次仍失败(' + reason + ')，需人工处置', item.body);
};

// 看门狗：防止 HTTP 节点异常未触发 catch 时 SENDING 永久卡死
const inflight = q.find(it => it.status === 'SENDING');
if (inflight) {
    if (inflight.sentAt && now - inflight.sentAt > 15000) {
        inflight.attempts = (inflight.attempts || 0) + 1;
        inflight.lastStatus = 'watchdog-timeout';
        delete inflight.sentAt;
        if (inflight.attempts > 3) {
            sendDead(inflight, 'watchdog-timeout');
        } else {
            inflight.status = 'PENDING';
            inflight.nextAt = now + RETRY_DELAYS[inflight.attempts - 1];
            flow.set('buf', q);
            node.warn('[重试] ' + inflight.id + ' 看门狗判定超时，' +
                      RETRY_DELAYS[inflight.attempts - 1] + 'ms 后第 ' + inflight.attempts + ' 次重试');
        }
    } else {
        node.status({ fill: 'blue', shape: 'dot', text: '在途 1 条，队列=' + q.length });
    }
    return null; // 单飞行守卫：有 SENDING 时绝不再发
}

const item = q.find(it => it.status === 'PENDING' && (it.nextAt || 0) <= now);
if (!item) {
    node.status({ fill: 'green', shape: 'dot', text: '空闲，队列=' + q.length });
    return null;
}
item.status = 'SENDING';
item.sentAt = now;
item.attempts = item.attempts || 0;
flow.set('buf', q);
msg.url = item.url;
msg.payload = item.body;
msg._qc = { id: item.id, type: item.type };
node.status({ fill: 'blue', shape: 'dot', text: '发送 ' + item.type + ' ' + item.id });
return msg;

// HTTP 响应 / 超时异常统一入口：成功出队；失败 1s/2s/4s 退避，3 次重试后死信
const q = flow.get('buf') || [];
const meta = msg._qc || {};
let i = q.findIndex(it => it.id === meta.id);
if (i < 0 && !meta.id) i = q.findIndex(it => it.status === 'SENDING');
if (i < 0) {
    node.warn('[响应忽略] 队列项不存在或已完成：' + (meta.id || '(无指纹)'));
    return null;
}
const item = q[i];
if (item.status !== 'SENDING') {
    node.warn('[响应忽略] 非在途状态 ' + item.status + '：' + item.id);
    return null;
}
const st = Number(msg.statusCode) || 0;
const body = (msg.payload && typeof msg.payload === 'object' && !Array.isArray(msg.payload)) ? msg.payload : {};
const errText = msg.error ? String(msg.error.message || msg.error.code || msg.error) : '';
const ok = !msg.error && st >= 200 && st < 300;

if (ok) {
    if (body.accepted === false) {
        q.splice(i, 1);
        flow.set('buf', q);
        node.warn('[MES拒绝] ' + item.id + ' accepted=false，按 M1 契约不重试：' + (body.error || ''));
        node.status({ fill: 'red', shape: 'ring', text: 'MES拒绝' });
        return null;
    }
    q.splice(i, 1);
    flow.set('buf', q);
    if (item.type === 'ng') {
        const orderNo = body.mesOrderNo || '';
        if (!orderNo) {
            node.warn('[回执缺失] NG单 ' + item.id + ' 已出队，但 MES 未返回 mesOrderNo');
            return null;
        }
        node.warn('[回执] MES工单号=' + orderNo + ' → 写回 LastMesOrderNo（不覆盖 CurrentWorkOrderId）');
        node.status({ fill: 'green', shape: 'dot', text: '开单成功 ' + orderNo });
        return {
            topic: 'ns=2;s=QCStation.LastMesOrderNo',
            action: 'write',
            payload: orderNo,
            datatype: 'String',
            _uaKind: 'write'
        };
    }
    const receiptNo = body.receiptNo || '';
    if (!receiptNo) {
        node.warn('[回执缺失] 报工 ' + item.id + ' 已出队，但 MES 未返回 receiptNo');
        return null;
    }
    node.warn('[报工回执] receiptNo=' + receiptNo + ' → 写回 LastMesOrderNo');
    node.status({ fill: 'green', shape: 'dot', text: '报工成功 ' + receiptNo });
    return {
        topic: 'ns=2;s=QCStation.LastMesOrderNo',
        action: 'write',
        payload: receiptNo,
            datatype: 'String',
        _uaKind: 'write'
    };
}

const reason = errText || ('HTTP ' + st);
item.attempts = (item.attempts || 0) + 1;
item.lastStatus = reason;
delete item.sentAt;
if (item.attempts > 3) {
    q.splice(i, 1);
    flow.set('buf', q);
    const dead = flow.get('dead') || [];
    dead.push(Object.assign({}, item, { failedAt: new Date().toISOString() }));
    if (dead.length > 100) dead.shift();
    flow.set('dead', dead);
    node.error('[死信FAILED] ' + item.type + ' ' + item.id + ' 重试3次仍失败(' + reason + ')，需人工处置', item.body);
    node.status({ fill: 'red', shape: 'dot', text: '死信 ' + item.id });
    return null;
}
const delay = [1000, 2000, 4000][item.attempts - 1];
item.status = 'PENDING';
item.nextAt = Date.now() + delay;
q[i] = item;
flow.set('buf', q);
node.warn('[重试] ' + item.type + ' ' + item.id + ' 失败(' + reason + ')，' +
          delay + 'ms 后第 ' + item.attempts + ' 次重试');
node.status({ fill: 'yellow', shape: 'ring', text: '退避 ' + delay + 'ms' });
return null;

// UA 读写/Method 结果校验；Method accepted=false 必须打印原因并阻断后续动作
const kind = msg._uaKind || '';
if (kind === 'write' || /LastMesOrderNo$/.test(String(msg.topic || ''))) {
    node.warn('[UA写回成功] ' + (msg.topic || ''));
    return null;
}
if (kind === 'read' || /DeviceStatus$/.test(String(msg.topic || ''))) {
    flow.set('hbFails', 0);
    return null;
}
const p = msg.payload;
let outs = null;
if (Array.isArray(p)) outs = p;
else if (p && Array.isArray(p.OutputArguments)) outs = p.OutputArguments;
else if (p && Array.isArray(p.outputArguments)) outs = p.outputArguments;
else if (p && Array.isArray(p.value)) outs = p.value;
const unwrap = v => (v && typeof v === 'object' && !Array.isArray(v) && v.value !== undefined) ? v.value : v;
const asText = v => {
    v = unwrap(v);
    if (v === undefined || v === null) return '';
    if (typeof v === 'object') return String(v.text || v.Text || JSON.stringify(v));
    return String(v);
};
if (outs && outs.length) {
    const accepted = unwrap(outs[0]);
    const summary = outs.length > 1 ? asText(outs[1]) : '';
    if (accepted === false) node.error('[UA拒绝] ' + summary + ' —— 已阻断后续动作', msg);
    else if (accepted === true) node.warn('[UA成功] ' + summary);
    else node.warn('[UA返回] ' + JSON.stringify(outs));
} else {
    node.warn('[UA返回] ' + JSON.stringify(p));
}
return null;

// UA 异常计数：心跳成功会由 fn_ua_result 清零；连续 3 次异常判定假死/断网
const n = Math.min((flow.get('hbFails') || 0) + 1, 3);
flow.set('hbFails', n);
const detail = msg.error ? String(msg.error.message || msg.error.code || msg.error) : 'unknown';
node.error('[UA异常 ' + n + '/3] ' + detail, msg);
if (n >= 3) node.error('[连接告警] 连续3次UA异常，疑似断网/假死；检查 SecureChannel 与订阅状态');
return null;

const wo = String(msg.payload || 'WO-20261109-001').trim();
msg.action = 'method';
msg._uaKind = 'method';
msg.objectId = 'ns=2;s=QCStation';
msg.methodId = 'ns=2;s=QCStation.StartInspection';
msg.topic = msg.methodId;
msg.inputArguments = [
    { dataType: 'String', value: wo },
    { dataType: 'UInt32', value: 5 }
];
return msg;

const wo = String(msg.payload || 'WO-20261109-001').trim();
msg.action = 'method';
msg._uaKind = 'method';
msg.objectId = 'ns=2;s=QCStation';
msg.methodId = 'ns=2;s=QCStation.CompleteWorkOrder';
msg.topic = msg.methodId;
msg.inputArguments = [{ dataType: 'String', value: wo }];
return msg;

const mode = String(msg.payload || 'ok').toLowerCase();
flow.set('mesMode', mode);
flow.set('timeoutUntil', mode === 'timeout' ? Date.now() + 10000 : 0);
node.warn('[MES故障注入] mode=' + mode +
          (mode === 'timeout' ? '（10s 后自动恢复 ok，用于验证 1s/2s/4s 退避）' : ''));
return null;

// 模拟 MES：NG 开单 + 同 SN 防重 + 故障注入
const now = Date.now();
let mode = String(flow.get('mesMode') || 'ok').toLowerCase();
const until = Number(flow.get('timeoutUntil') || 0);
if (mode === 'timeout' && until && now >= until) {
    mode = 'ok';
    flow.set('mesMode', 'ok');
    flow.set('timeoutUntil', 0);
}
const body = msg.payload;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
    msg.statusCode = 400;
    msg.payload = { accepted: false, error: 'invalid JSON body' };
    return [msg, null];
}
const required = ['workOrderId', 'serialNumber', 'defectType', 'confidence', 'imageId', 'occurredAt'];
const missing = required.filter(k => !(k in body));
if (missing.length) {
    msg.statusCode = 400;
    msg.payload = { accepted: false, error: 'missing fields: ' + missing.join(',') };
    return [msg, null];
}
if (typeof body.occurredAt !== 'string' || !/Z$/.test(body.occurredAt)) {
    msg.statusCode = 400;
    msg.payload = { accepted: false, error: 'occurredAt must be ISO8601 UTC with Z' };
    return [msg, null];
}
const orders = flow.get('orders') || {};
const makeOrder = () => {
    const seq = (flow.get('mesSeq') || 0) + 1;
    flow.set('mesSeq', seq);
    const d = new Date();
    const no = 'MES-' + d.toISOString().slice(0, 10).replace(/-/g, '') + '-' + String(seq).padStart(4, '0');
    orders[body.serialNumber] = no;
    flow.set('orders', orders);
    return no;
};
const existing = orders[body.serialNumber];
if (existing) {
    msg.statusCode = 200;
    msg.payload = { accepted: true, mesOrderNo: existing, duplicated: true };
    return [msg, null];
}
if (mode === '5xx') {
    msg.statusCode = 500;
    msg.payload = { accepted: false, error: 'simulated 5xx' };
    return [msg, null];
}
if (mode === 'timeout') {
    node.warn('[MES注入timeout] NG单 ' + body.serialNumber + ' 延迟 10s 响应');
    setTimeout(() => {
        try {
            if (msg.res && (msg.res.finished || msg.res.writableEnded)) {
                node.warn('[MES超时模拟] 客户端已超时断开，丢弃延迟响应');
                return;
